let notes=[];
let filter={topic:'All',pattern:'All',difficulty:'All',status:'All',sort:'Sheet order'};
let searchIndex=0;
let searchMatches=[];
const app=document.querySelector('#app');
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s??'').toLowerCase().replace(/[^a-z0-9]/g,'');
const slug=s=>String(s).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const url=n=>`#/problem/${n.id}`;
const getProgress=()=>{try{return JSON.parse(localStorage.getItem('dsa-progress')||'{}')}catch{return {}}};
const progress=n=>getProgress()[n.id]||{};
function setProgress(n,patch){const all=getProgress();all[n.id]={...all[n.id],...patch};localStorage.setItem('dsa-progress',JSON.stringify(all));render();toast(patch.status==='revised'?'Marked as revised ✓':patch.status==='needs'?'Added to revision queue':'Progress updated')}
const statusOf=n=>progress(n).status||'not-started';
const revised=()=>notes.filter(n=>statusOf(n)==='revised').length;
const patterns=()=>[...new Set(notes.map(n=>n.pattern))].sort((a,b)=>a.localeCompare(b));
const inline=s=>esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
function markdown(raw){
  const lines=String(raw||'').split('\n');let html='',list=null;
  const close=()=>{if(list){html+=`</${list}>`;list=null}};
  for(let i=0;i<lines.length;i++){
    const line=lines[i].trim();
    if(!line){close();continue}
    if(line.startsWith('|')&&lines[i+1]?.trim().match(/^\|?\s*[-:| ]+\s*\|?$/)){
      close();const cells=s=>s.trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim());
      html+='<div class="markdown-table-wrap"><table class="markdown-table"><thead><tr>'+cells(line).map(x=>`<th>${inline(x)}</th>`).join('')+'</tr></thead><tbody>';i++;
      while(lines[i+1]?.trim().startsWith('|')){i++;html+='<tr>'+cells(lines[i]).map(x=>`<td>${inline(x)}</td>`).join('')+'</tr>'}
      html+='</tbody></table></div>';continue;
    }
    let m=line.match(/^\d+\.\s+(.+)$/);
    if(m){if(list!=='ol'){close();html+='<ol>';list='ol'}html+=`<li>${inline(m[1])}</li>`;continue}
    m=line.match(/^[-*]\s+(.+)$/);
    if(m){if(list!=='ul'){close();html+='<ul>';list='ul'}html+=`<li>${inline(m[1])}</li>`;continue}
    close();html+=`<p>${inline(line)}</p>`;
  }
  close();return html;
}
const badge=n=>`<span class="badge ${esc(n.difficulty)}">${esc(n.difficulty)}</span>`;
const statusLabel=n=>statusOf(n)==='revised'?'Revised':statusOf(n)==='needs'?'Needs revision':'Not started';
function row(n){const st=statusOf(n);return `<div class="problem-row"><span class="problem-number">${String(n.id).padStart(2,'0')}</span><a href="${url(n)}" class="problem-main"><div class="problem-title">${esc(n.title)}</div><div class="problem-sub">${esc(n.topic)} · ${esc(n.pattern)}</div></a>${badge(n)}<span class="row-status"><i class="status-dot ${st}"></i>${statusLabel(n)}</span><button class="star-button ${st==='needs'?'active':''}" data-action="flag" data-id="${n.id}" aria-label="${st==='needs'?'Remove revision flag':'Flag for revision'}: ${esc(n.title)}" title="Flag for revision">${st==='needs'?'★':'☆'}</button></div>`}
function topicCard(topic,description,icon){const list=notes.filter(n=>n.topic===topic),done=list.filter(n=>statusOf(n)==='revised').length;return `<a class="topic-card" href="#/topics/${slug(topic)}"><div class="topic-icon">${icon}</div><h3>${topic}</h3><p>${description}</p><div class="card-bottom"><span>${list.length} problems · ${done} revised</span><span>Explore ↗</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.round(done/list.length*100)}%"></div></div></a>`}
function home(){const pct=Math.round(revised()/notes.length*100);app.innerHTML=`<section class="hero"><div class="wrap hero-inner"><span class="eyebrow">DSA Notebook</span><h1>Revise with<br>clarity.</h1><p>Every problem. One idea. One dry run.</p><div class="hero-actions"><a class="pill" href="#/revise">Start revising ↗</a><a class="pill ghost" href="#/topics">Browse topics ›</a></div><div class="hero-visual" aria-label="An array scan finds the maximum value"><div class="visual-top"><span>Linear scan · find the maximum</span><span>O(n)</span></div><div class="visual-array"><span>3</span><span>2</span><span>1</span><span class="active">5</span><span>4</span></div><div class="visual-bottom">max = 5 &nbsp;·&nbsp; scan once, remember the best</div></div></div></section><div class="stats"><div class="wrap stats-inner"><div class="stat"><strong>${notes.length}</strong><span>Problems</span></div><div class="stat"><strong>2</strong><span>Topics</span></div><div class="stat"><strong>${patterns().length}</strong><span>Patterns</span></div><div class="stat"><strong>${pct}%</strong><span>Revised</span></div></div></div><section class="section alt" id="topics"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">Your library</span><h2>Find your focus.</h2><p>Start with a topic, then follow each problem from the question to the core idea.</p></div><a class="text-link" href="#/topics">All problems ›</a></div><div class="topic-grid">${topicCard('Arrays','From linear scans to intervals and matrix traversal.','[ ]')}${topicCard('Sorting','Compare, partition, merge, and build intuition.','↕')}</div></div></section><section class="section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">Think in patterns</span><h2>Recognize the move.</h2><p>Practice the underlying technique across problems, not just the answer to one question.</p></div><a class="text-link" href="#/patterns">Explore patterns ›</a></div><div class="chip-row">${['Two Pointers','Sliding Window','Prefix Sum + Hash Map','Merge Sort','Binary Search on Answer','Hash Map'].filter(p=>patterns().includes(p)).map(p=>`<a class="chip" href="#/patterns/${encodeURIComponent(p)}">${esc(p)}</a>`).join('')}</div></div></section><section class="section alt"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">Ready when you are</span><h2>Make recall a habit.</h2><p>Flag weak spots, hide the code until you have an answer, and mark each review as done.</p></div><a class="pill" href="#/revise">Open revision queue ↗</a></div></div></section>`}
function options(values,selected){return values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}
function filters(){return `<div class="filters"><select class="filter-select" data-filter="topic" aria-label="Filter topic">${options(['All','Arrays','Sorting'],filter.topic)}</select><select class="filter-select" data-filter="pattern" aria-label="Filter pattern">${options(['All',...patterns()],filter.pattern)}</select><select class="filter-select" data-filter="difficulty" aria-label="Filter difficulty">${options(['All','Easy','Medium','Hard'],filter.difficulty)}</select><select class="filter-select" data-filter="status" aria-label="Filter status">${options(['All','Needs revision','Revised','Not started'],filter.status)}</select><select class="filter-select" data-filter="sort" aria-label="Sort problems">${options(['Sheet order','Last revised','Difficulty'],filter.sort)}</select><span class="filter-count" id="result-count"></span><button type="button" class="clear-button" data-action="clear-filters">Clear filters</button></div>`}
function filtered(){let result=notes.filter(n=>(filter.topic==='All'||n.topic===filter.topic)&&(filter.pattern==='All'||n.pattern===filter.pattern)&&(filter.difficulty==='All'||n.difficulty===filter.difficulty)&&(filter.status==='All'||statusLabel(n)===filter.status));if(filter.sort==='Last revised')result.sort((a,b)=>(progress(b).lastRevised||0)-(progress(a).lastRevised||0));if(filter.sort==='Difficulty')result.sort((a,b)=>['Easy','Medium','Hard'].indexOf(a.difficulty)-['Easy','Medium','Hard'].indexOf(b.difficulty));return result}
function updateList(){const result=filtered();const target=$('#list-results');if(!target)return;target.innerHTML=result.length?result.map(row).join(''):`<div class="empty"><h3>Nothing here yet.</h3><p>Try a different filter to find your next problem.</p><button class="pill secondary" data-action="clear-filters">Clear filters</button></div>`;$('#result-count').textContent=`${result.length} of ${notes.length} problems`}
function catalog(kind,arg){if(kind==='topic'){filter={...filter,topic:arg==='sorting'?'Sorting':arg==='arrays'?'Arrays':'All'}}if(kind==='pattern'){filter={...filter,pattern:patterns().find(p=>p===decodeURIComponent(arg))||'All'}}const heading=kind==='topic'&&filter.topic!=='All'?filter.topic:kind==='pattern'&&filter.pattern!=='All'?filter.pattern:'Explore every problem.';app.innerHTML=`<div class="wrap"><div class="catalog-head"><span class="eyebrow">${kind==='pattern'?'Pattern index':'Problem library'}</span><h1>${esc(heading)}</h1><p>${kind==='pattern'?'Explore the techniques behind the solutions. Pick a pattern to see every matching note.':'Find the right problem, follow the idea, and test your recall before you reveal the code.'}</p></div>${kind==='pattern'?`<div class="chip-row">${patterns().map(p=>`<a class="chip ${filter.pattern===p?'active':''}" href="#/patterns/${encodeURIComponent(p)}">${esc(p)}</a>`).join('')}</div>`:''}${filters()}<div class="problem-list" id="list-results"></div></div>`;updateList()}
function note(id){const n=notes.find(x=>x.id===id);if(!n){notFound();return}const idx=notes.indexOf(n),prev=notes[idx-1],next=notes[idx+1],st=statusOf(n);document.title=`${n.title} — DSA Notebook`;app.innerHTML=`<div class="wrap"><header class="note-header"><div class="breadcrumbs"><a href="#/">Home</a><span>›</span><a href="#/topics">Topics</a><span>›</span><a href="#/topics/${slug(n.topic)}">${esc(n.topic)}</a><span>›</span><span>${esc(n.title)}</span></div><div class="note-title-row"><h1>${esc(n.title)}</h1><div class="note-actions"><button class="pill secondary" data-action="flag" data-id="${n.id}">${st==='needs'?'★ Needs revision':'☆ Flag to revise'}</button><button class="pill" data-action="revised" data-id="${n.id}">${st==='revised'?'✓ Revised':'Mark revised'}</button></div></div><div class="note-meta"><span class="chip">${esc(n.topic)}</span><a class="chip" href="#/patterns/${encodeURIComponent(n.pattern)}">${esc(n.pattern)}</a>${badge(n)}<span>· #${n.id}</span><a href="${esc(n.link)}" target="_blank" rel="noopener noreferrer">Original problem ↗</a></div></header><div class="note-layout"><article class="note-article"><section class="note-section" id="problem"><h2>Problem</h2><div class="note-copy">${markdown(n.problem)}</div></section><section class="note-section" id="core-idea"><div class="callout"><span class="eyebrow">The core idea</span><div class="note-copy">${markdown(n.idea)}</div></div></section><section class="note-section" id="approach"><h2>Approach</h2><div class="note-copy">${markdown(n.approach)}</div></section><section class="note-section" id="dry-run"><h2>Dry run</h2><div class="note-copy">${markdown(n.dryRun)}</div></section><section class="note-section" id="complexity"><h2>Complexity</h2><div class="complexity-grid"><div class="complexity-card"><span>Time</span><strong>${esc(n.time)}</strong></div><div class="complexity-card"><span>Space</span><strong>${esc(n.space)}</strong></div></div></section><section class="note-section" id="code"><h2>Solution</h2><details class="solution"><summary>Try writing it first, then reveal the code</summary><div class="code-toolbar"><span>${esc(n.language.toUpperCase())}</span><button type="button" class="copy-button" data-action="copy" data-id="${n.id}">Copy code</button></div><pre class="code-block"><code>${esc(n.code)}</code></pre></details></section><nav class="note-nav" aria-label="Problem navigation">${prev?`<a href="${url(prev)}">← ${esc(prev.title)}</a>`:'<span></span>'}${next?`<a href="${url(next)}">${esc(next.title)} →</a>`:'<span></span>'}</nav></article><aside class="note-aside" aria-label="On this page"><h3>On this page</h3>${[['problem','Problem'],['core-idea','Core idea'],['approach','Approach'],['dry-run','Dry run'],['complexity','Complexity'],['code','Solution']].map(([id,label])=>`<a href="#${id}" data-scroll="${id}">${label}</a>`).join('')}</aside></div></div>`;window.scrollTo(0,0)}
function revise(){const due=notes.filter(n=>statusOf(n)==='needs'),todo=notes.filter(n=>statusOf(n)==='not-started');app.innerHTML=`<div class="wrap"><div class="catalog-head"><span class="eyebrow">Your revision space</span><h1>Pick up where you left off.</h1><p>Your flags and completed reviews stay on this device. Choose a weak spot, or let the notebook pick one for you.</p></div><div class="queue-grid"><div class="queue-card"><strong>${due.length}</strong><span>Needs revision</span></div><div class="queue-card"><strong>${revised()}</strong><span>Revised</span></div><div class="queue-card"><strong>${todo.length}</strong><span>Not started</span></div></div><div class="revise-actions"><button class="pill" data-action="random">Surprise me ↗</button><a class="pill secondary" href="#/topics">Browse all problems</a></div><div class="section-heading"><div><span class="eyebrow">Your queue</span><h2>${due.length?'Needs another look.':'A clean slate.'}</h2><p>${due.length?'Return to the problems you flagged for a second pass.':'Flag any problem from its note page to build a focused queue.'}</p></div></div><div class="problem-list">${due.length?due.map(row).join(''):`<div class="empty"><h3>No flagged problems.</h3><p>Browse the library or try a random problem to begin.</p></div>`}</div></div>`}
function notFound(){app.innerHTML=`<div class="wrap catalog-head"><span class="eyebrow">Page not found</span><h1>Let’s find another path.</h1><p>The note you requested is not here.</p><a class="pill" href="#/topics">Browse problems</a></div>`}
function render(){document.title='DSA Notebook — Revise with clarity';const route=decodeURI(location.hash.slice(1)||'/').split('/').filter(Boolean);if(!route.length)home();else if(route[0]==='problem')note(route[1]);else if(route[0]==='topics')catalog('topic',route[1]);else if(route[0]==='patterns')catalog('pattern',route.slice(1).join('/'));else if(route[0]==='revise')revise();else notFound();document.querySelectorAll('.nav-links a').forEach(a=>a.classList.toggle('active',a.getAttribute('href').includes(route[0]||'___')));$('#nav-links').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false')}
let toastTimer;function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
function openSearch(){const box=$('#search-backdrop');box.hidden=false;document.body.style.overflow='hidden';$('#search-input').value='';updateSearch();$('#search-input').focus()}
function closeSearch(){const box=$('#search-backdrop');box.hidden=true;document.body.style.overflow='';$('#search-open').focus()}
function updateSearch(){const q=$('#search-input').value.trim(),nq=norm(q);searchMatches=q?notes.map(n=>({n,score:(norm(n.title).includes(nq)?6:0)+(norm(n.pattern).includes(nq)?3:0)+(norm(n.topic).includes(nq)?1:0)+(norm(n.title+' '+n.pattern).includes(nq)?1:0)})).filter(x=>x.score).sort((a,b)=>b.score-a.score).slice(0,9).map(x=>x.n):[];searchIndex=0;$('#search-results').innerHTML=searchMatches.length?searchMatches.map((n,i)=>`<button type="button" class="search-result ${i===0?'selected':''}" data-action="open-result" data-id="${n.id}"><span><strong>${esc(n.title)}</strong><small>${esc(n.topic)} · ${esc(n.pattern)}</small></span>${badge(n)}</button>`).join(''):`<div class="empty"><h3>${q?'No matching problems':'Search the notebook'}</h3><p>${q?'Try another title or pattern.':'Try “two pointers”, “merge sort”, or “maximum”.'}</p></div>`}
$('#year').textContent=new Date().getFullYear();
$('#search-open').addEventListener('click',openSearch);$('#search-close').addEventListener('click',closeSearch);$('#search-backdrop').addEventListener('click',e=>{if(e.target.id==='search-backdrop')closeSearch()});$('#search-input').addEventListener('input',updateSearch);
$('#theme-button').addEventListener('click',()=>{const current=document.documentElement.dataset.theme,next={system:'light',light:'dark',dark:'system'}[current]||'system';document.documentElement.dataset.theme=next;localStorage.setItem('dsa-theme',next);toast(`Theme: ${next}`)});
$('#menu-button').addEventListener('click',()=>{const menu=$('#nav-links'),open=!menu.classList.contains('open');menu.classList.toggle('open',open);$('#menu-button').setAttribute('aria-expanded',String(open))});
document.addEventListener('click',async e=>{const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return}const btn=e.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action,n=notes.find(x=>x.id===btn.dataset.id);if(action==='flag'){setProgress(n,{status:statusOf(n)==='needs'?'not-started':'needs'});return}if(action==='revised'){setProgress(n,{status:'revised',lastRevised:Date.now()});return}if(action==='clear-filters'){filter={topic:'All',pattern:'All',difficulty:'All',status:'All',sort:'Sheet order'};render();return}if(action==='copy'){try{await navigator.clipboard.writeText(n.code);toast('Code copied ✓')}catch{toast('Copy unavailable in this browser')}return}if(action==='random'){const pool=notes.filter(x=>statusOf(x)==='needs');location.hash=url((pool.length?pool:notes)[Math.floor(Math.random()*(pool.length||notes.length))]);return}if(action==='open-result'){closeSearch();location.hash=url(n)}});
document.addEventListener('change',e=>{const control=e.target.closest('[data-filter]');if(control){filter[control.dataset.filter]=control.value;updateList()}});
document.addEventListener('keydown',e=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if((e.key==='/'&&!typing)||(e.key.toLowerCase()==='k'&&(e.ctrlKey||e.metaKey))){e.preventDefault();openSearch();return}if(!$('#search-backdrop').hidden){if(e.key==='Escape'){e.preventDefault();closeSearch()}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();searchIndex=Math.max(0,Math.min(searchMatches.length-1,searchIndex+(e.key==='ArrowDown'?1:-1)));document.querySelectorAll('.search-result').forEach((x,i)=>x.classList.toggle('selected',i===searchIndex));document.querySelectorAll('.search-result')[searchIndex]?.scrollIntoView({block:'nearest'})}if(e.key==='Enter'&&searchMatches[searchIndex]){closeSearch();location.hash=url(searchMatches[searchIndex])}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
window.addEventListener('scroll',()=>{const total=document.documentElement.scrollHeight-innerHeight;$('#reading-progress').style.width=location.hash.startsWith('#/problem/')&&total>0?`${scrollY/total*100}%`:'0'}, {passive:true});
fetch('notes.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(data=>{notes=data;render()}).catch(()=>{app.innerHTML='<div class="wrap empty"><h2>Notes could not load.</h2><p>Please reload the page.</p></div>'});
